//! 🧪️ Real failure-node births keep their original action, allocator marker and pending post.
use super::*;
use crate::{NativeAllocationBudget,NativeAllocationEvent,OriginalWorkAuthority,OriginalWorkState,OriginalWork,OriginalWorkRecipient};
use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread};
use std::sync::{Arc,atomic::{AtomicUsize,AtomicBool,Ordering}};
struct PartialSource{checks:Arc<AtomicUsize>,recoveries:Arc<AtomicUsize>,pending:Arc<AtomicBool>,refusal:Arc<std::sync::Mutex<Option<ValueError>>>,panic:Arc<AtomicBool>}
impl OriginalWorkRecipient for PartialSource{
 type Context<'turn,'source>=() where 'source:'turn;
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn validate_context<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn admits<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,quote:crate::OriginalWorkQuote<'reply>,observed:u64,additional:u64)->crate::OriginalWorkQuoteComplete<'reply>where 'source:'turn{quote.complete(Ok(observed.checked_add(additional)==Some(1)))}
 fn settle_partial<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,check:crate::OriginalWorkPartialCheck<'reply>)->crate::OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{self.checks.fetch_add(1,Ordering::SeqCst);let refusal=self.refusal.lock().unwrap().take();if let Some(error)=refusal{let completed=check.complete(Err(error));if self.panic.swap(false,Ordering::SeqCst){panic!("original partial Source recorded its owned refusal")}return completed}if self.pending.swap(false,Ordering::SeqCst){check.pending()}else{check.complete(Ok(()))}}
 fn recover_partial<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,check:crate::OriginalWorkPartialCheck<'reply>)->crate::OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{self.recoveries.fetch_add(1,Ordering::SeqCst);check.complete(Ok(()))}
}
struct Funding{birth:OriginalFailureStorageBirth,pool:OriginalFailureStoragePool,state:OriginalWorkState,work:OriginalWorkAuthority<PartialSource>,checks:Arc<AtomicUsize>,recoveries:Arc<AtomicUsize>,partial_pending:Arc<AtomicBool>,partial_refusal:Arc<std::sync::Mutex<Option<ValueError>>>,partial_panic:Arc<AtomicBool>,budget:NativeAllocationBudget,prepare_allowed:bool,quote_refused:bool,quote_pending:bool,recorded_quote:Option<Result<RetainedCloneGrant,NativeAllocationRefusal>>,post_pending:bool,post_panic:bool,recorded_post:Option<Result<(),NativeAllocationRefusal>>,post_refusal:Option<NativeAllocationRefusal>,quotes:usize,posts:usize,prepared:usize,posted_marker:Option<usize>,admitted:usize,commit_refusal:Option<ValueError>,finish_refusal:Option<ValueError>,commits:usize,finishes:usize}
struct WorkRestore<'slot,'loan>{work:OriginalWork<'loan>,slot:&'slot mut OriginalWorkState}
impl Drop for WorkRestore<'_,'_>{fn drop(&mut self){*self.slot=self.work.state.take()}}
impl Funding{
 fn new()->Self{let checks=Arc::new(AtomicUsize::new(0));let recoveries=Arc::new(AtomicUsize::new(0));let partial_pending=Arc::new(AtomicBool::new(false));let partial_refusal=Arc::new(std::sync::Mutex::new(None));let partial_panic=Arc::new(AtomicBool::new(false));Self{birth:Default::default(),pool:Default::default(),state:OriginalWorkState::fresh(),work:OriginalWorkAuthority::new(PartialSource{checks:checks.clone(),recoveries:recoveries.clone(),pending:partial_pending.clone(),refusal:partial_refusal.clone(),panic:partial_panic.clone()}),checks,recoveries,partial_pending,partial_refusal,partial_panic,budget:Default::default(),prepare_allowed:true,quote_refused:false,quote_pending:false,recorded_quote:None,post_pending:false,post_panic:false,recorded_post:None,post_refusal:None,quotes:0,posts:0,prepared:0,posted_marker:None,admitted:0,commit_refusal:None,finish_refusal:None,commits:0,finishes:0}}
 fn with_work<T>(&mut self,operation:impl FnOnce(&mut OriginalWork<'_>,&mut OriginalFailureStorageBirth)->T)->T{let state=&mut self.state;let birth=&mut self.birth;self.work.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let original=OriginalWork{state:state.take(),recipient:Some(&mut loan)};let mut restore=WorkRestore{work:original,slot:state};operation(&mut restore.work,birth)}).unwrap()}
 fn release(&mut self){while !self.pool.is_empty(){self.pool.release_one(OriginalFailureStorage::birth_bytes()).unwrap();}assert!(!self.state.has_live_actions()&&!self.work.has_live_actions());}
}
impl OriginalFailureFunding for Funding{
 fn birth(&mut self)->&mut OriginalFailureStorageBirth{&mut self.birth}
 fn performed_scope(&mut self)->Result<OriginalFailurePerformedScope<'_>,ValueError>{self.with_work(|work,birth|work.validate_action_source(birth.work_action()))?;OriginalFailurePerformedScope::new(&mut self.state,&mut self.birth,&mut self.pool)}
 fn settle_performed(&mut self)->OriginalFailureStorageStep<(),ValueError>{self.with_work(|work,birth|birth.settle_performed(work))}
 fn prepare(&mut self,work:u64)->OriginalFailureStorageStep<bool,ValueError>{self.prepared+=1;if !self.prepare_allowed{return OriginalFailureStorageStep::Complete(Ok(false))}self.with_work(|original,birth|{if birth.work_action().is_none(){original.begin_turn()}match original.prepare_for_action(work,birth.work_action_output().unwrap()){Ok(Some(accepted))=>OriginalFailureStorageStep::Complete(Ok(accepted)),Ok(None)=>OriginalFailureStorageStep::Pending,Err(error)=>OriginalFailureStorageStep::Complete(Err(error))}})}
 fn quote(&mut self,demand:RetirementDemand,grant:RetainedCloneGrant)->OriginalFailureStorageStep<RetainedCloneGrant>{if self.recorded_quote.is_none(){self.quotes+=1;assert_eq!(self.state.actual(),0);assert!(self.state.action_identity().is_some());let request=NativeAllocationRequest{bytes:demand.capacity_bytes,owned_bytes:0,next_owned_bytes:demand.capacity_bytes,maximum_bytes:demand.capacity_bytes};self.birth.install_request(request).unwrap();self.recorded_quote=Some(if self.quote_refused{Err(invalid("original quote refused").into())}else{self.budget.receive(NativeAllocationEvent::Quote(request),grant,true).map(|()|grant).map_err(Into::into)});}if self.quote_pending{self.quote_pending=false;return OriginalFailureStorageStep::Pending}OriginalFailureStorageStep::Complete(self.recorded_quote.take().unwrap())}
 fn post(&mut self,grant:RetainedCloneGrant,progress:RetainedCloneProgress)->OriginalFailureStorageStep<()>{assert!(self.with_work(|work,birth|work.validates(birth.work_proof().unwrap(),1).unwrap()));if self.post_pending{self.post_pending=false;return OriginalFailureStorageStep::Pending}if self.recorded_post.is_none(){self.posts+=1;self.posted_marker=self.birth.actual();let request=self.birth.request().unwrap();let verdict=self.budget.receive(NativeAllocationEvent::Post{request,actual:progress.retained_capacity_bytes},grant,true).map_err(Into::into);self.admitted=request.next_owned_bytes;self.recorded_post=Some(match verdict{Ok(())=>self.post_refusal.take().map_or(Ok(()),Err),Err(error)=>Err(error)});if self.post_panic{self.post_panic=false;panic!("actual original post interrupted after recording its verdict")}}OriginalFailureStorageStep::Complete(self.recorded_post.take().unwrap())}
 fn cancel(&mut self)->OriginalFailureStorageStep<()>{let request=self.birth.request().unwrap();OriginalFailureStorageStep::Complete(self.budget.receive(NativeAllocationEvent::Cancel(request),self.birth.quoted_grant().unwrap(),true).map_err(Into::into))}
 fn pool(&mut self)->&mut OriginalFailureStoragePool{&mut self.pool}
 fn commit(&mut self,actual:u128)->Result<(),ValueError>{self.commits+=1;if let Some(error)=self.commit_refusal.take(){return Err(error)}assert!(!self.pool.is_empty()||self.birth.actual()==Some(0)||self.birth.actual().is_none());self.with_work(|work,birth|{let action=birth.work_action();if work.commit_for_action(actual,action,birth.work_proof_output()?)?{Ok(())}else{Err(invalid("actual original work exceeds its quote"))}})}
 fn cancel_work(&mut self)->Result<(),ValueError>{self.with_work(|work,birth|work.cancel_for_action(birth.work_action_slot()?))}
 fn finish_work(&mut self)->Result<(),ValueError>{self.finishes+=1;if let Some(error)=self.finish_refusal.take(){return Err(error)}self.with_work(|work,birth|{let(proof,action)=birth.finishing_work_slots()?;work.finish_for_action(proof,action)})}
}
fn complete(poll:crate::RetainedWorkPoll<RetainedCloneStep,OriginalRetirementFailure>)->RetainedWorkOutcome<RetainedCloneStep,OriginalRetirementFailure>{match poll{crate::RetainedWorkPoll::Complete(turn)=>turn,crate::RetainedWorkPoll::Pending{..}=>panic!("original failure birth remains pending")}}
fn grant()->RetainedCloneGrant{let demand=OriginalFailureStorage::birth_demand();RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_depth:demand.depth,..Default::default()}}
#[test]
fn denial_precedes_the_original_allocation_quote(){let law:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();let mut funding=Funding::new();funding.prepare_allowed=law["cases"][0]["prepare"].as_bool().unwrap();let(turn,heap)=observe(||complete(refill_original_failure_storage(&mut funding,grant())));assert_eq!(heap,(0,0));assert_eq!(turn.work,0);assert_eq!(funding.quotes,0);assert!(funding.birth.terminal_is_empty());assert!(funding.pool.is_empty());funding.release();}
#[test]
fn actual_null_allocator_posts_zero_and_commits_the_original_requested_admission(){let mut funding=Funding::new();funding.post_refusal=Some(invalid("actual original post refusal").into());let((turn,refused),heap)=observe(||refuse_one_allocation_on_this_thread(||complete(refill_original_failure_storage(&mut funding,grant()))));assert_eq!((refused,heap),(1,(0,0)));assert_eq!(turn.work,1);assert_eq!(funding.state.actual(),1);assert_eq!(funding.posted_marker,Some(0));assert_eq!(funding.admitted,OriginalFailureStorage::birth_bytes());let error=turn.result.unwrap_err();assert_eq!(error.primary().unwrap().kind,ValueRefusalKind::AllocationFailed);assert_eq!(error.allocation_refusal().unwrap().owned().unwrap().message,"actual original post refusal");assert!(funding.birth.terminal_is_empty()&&funding.pool.is_empty());funding.release();}
#[test]
fn post_pending_keeps_the_real_proof_and_invoices_effects_exactly_once(){let mut funding=Funding::new();funding.post_pending=true;let(first,heap)=observe(||refill_original_failure_storage(&mut funding,grant()));assert!(matches!(first,crate::RetainedWorkPoll::Pending{..}));let progress=funding.birth.progress();assert_eq!(heap,(OriginalFailureStorage::birth_bytes(),0));assert_eq!(progress.retained_capacity_bytes,heap.0);assert_eq!(first.work(),1);assert_eq!(funding.posts,0);assert!(funding.birth.work_proof().is_some()&&funding.state.has_live_actions());let(second,heap)=observe(||complete(refill_original_failure_storage(&mut funding,grant())));assert_eq!(heap,(0,0));assert_eq!(second.work,0);assert_eq!(second.result.unwrap().progress().retained_capacity_bytes,OriginalFailureStorage::birth_bytes());assert_eq!((funding.prepared,funding.quotes,funding.posts),(1,1,1));assert_eq!(funding.state.actual(),1);assert!(funding.birth.terminal_is_empty());funding.release();}
#[test]
fn actual_post_unwind_retains_node_proof_and_exact_original_verdict(){let mut funding=Funding::new();funding.post_panic=true;let(result,heap)=observe(||std::panic::catch_unwind(std::panic::AssertUnwindSafe(||complete(refill_original_failure_storage(&mut funding,grant())))));assert!(result.is_err());assert!(heap.0>=OriginalFailureStorage::birth_bytes());assert_eq!(funding.posts,1);assert_eq!(funding.state.actual(),1);assert!(funding.birth.work_proof().is_some()&&!funding.pool.is_empty());let(turn,heap)=observe(||complete(refill_original_failure_storage(&mut funding,grant())));assert_eq!(heap,(0,0));assert_eq!(turn.work,1);assert_eq!(turn.result.unwrap().progress().retained_capacity_bytes,OriginalFailureStorage::birth_bytes());assert_eq!(funding.posts,1);assert!(funding.birth.terminal_is_empty());funding.release();}
#[test]
fn occupied_physical_marker_refuses_before_another_allocator_attempt(){let mut actual=None;let(storage,_)=super::super::custody_tests::admit_node(OriginalFailureStorage::birth_bytes(),&mut actual).result.unwrap();let original=actual;let(turn,heap)=observe(||super::super::custody_tests::admit_node(OriginalFailureStorage::birth_bytes(),&mut actual));assert_eq!(heap,(0,0));assert_eq!(turn.work,0);assert!(turn.result.is_err());assert_eq!(actual,original);storage.release(OriginalFailureStorage::birth_bytes()).unwrap();}

#[test]
fn pending_quote_retains_its_original_admission_and_reports_the_later_allocator_once(){let law:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();let mut funding=Funding::new();funding.quote_pending=true;let(first,heap)=observe(||refill_original_failure_storage(&mut funding,grant()));assert_eq!(heap,(0,0));assert_eq!(first.work(),u128::from(law["quoteResume"]["firstWork"].as_u64().unwrap()));assert!(matches!(first,crate::RetainedWorkPoll::Pending{..}));assert_eq!(funding.birth.progress().retained_capacity_bytes,law["quoteResume"]["firstCapacity"].as_u64().unwrap()as usize);assert_eq!(funding.birth.phase(),OriginalFailureStorageBirthPhase::Quote);assert!(funding.birth.work_action().is_some()&&funding.birth.work_proof().is_none());assert!(funding.state.has_live_actions()&&funding.budget.pending().is_some());let original_request=funding.birth.request();let foreign=RetainedCloneGrant{maximum_capacity_bytes:grant().maximum_capacity_bytes+1,..grant()};let(refused,heap)=observe(||complete(refill_original_failure_storage(&mut funding,foreign)));assert_eq!(heap,(0,0));assert_eq!(refused.work,u128::from(law["foreignGrant"]["work"].as_u64().unwrap()));assert!(refused.result.is_err());assert_eq!(funding.birth.request(),original_request);assert!(funding.budget.pending().is_some()&&funding.recorded_quote.is_some());let(second,heap)=observe(||complete(refill_original_failure_storage(&mut funding,grant())));assert_eq!(heap,(OriginalFailureStorage::birth_bytes(),0));assert_eq!(second.work,u128::from(law["quoteResume"]["resumedWork"].as_u64().unwrap()));assert_eq!(second.result.unwrap().progress().retained_capacity_bytes,heap.0);assert_eq!(funding.prepared,law["quoteResume"]["prepareCalls"].as_u64().unwrap()as usize);assert_eq!(funding.quotes,law["quoteResume"]["quoteCalls"].as_u64().unwrap()as usize);assert_eq!(funding.state.actual(),1);assert!(funding.birth.terminal_is_empty()&&funding.budget.terminal_is_empty());funding.release();}
#[test]
fn refused_original_quote_cancels_its_real_unobserved_work_action(){let mut funding=Funding::new();funding.quote_refused=true;let(turn,heap)=observe(||complete(refill_original_failure_storage(&mut funding,grant())));assert_eq!(heap,(0,0));assert_eq!(turn.work,0);let error=turn.result.unwrap_err();assert_eq!(error.allocation_refusal().unwrap().owned().unwrap().message,"original quote refused");assert_eq!((funding.prepared,funding.quotes,funding.posts),(1,1,0));assert_eq!(funding.state.actual(),0);assert!(funding.state.action_identity().is_none()&&funding.birth.terminal_is_empty()&&funding.budget.terminal_is_empty());funding.release();}

#[test]
fn later_work_refusal_preserves_both_owned_causes_without_reallocation(){let law:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();let first=ValueError::new(ValueRefusalKind::WorkLimit,law["refusalOrder"][0].as_str().unwrap().to_owned());let later=ValueError::new(ValueRefusalKind::Canceled,law["refusalOrder"][1].as_str().unwrap().to_owned());let pointers=[first.message.as_ptr(),later.message.as_ptr()];let mut birth=OriginalFailureStorageBirth::default();birth.phase=OriginalFailureStorageBirthPhase::CancelWork;let(_,heap)=observe(||{birth.retain_work_refusal(first).unwrap();birth.retain_work_refusal(later).unwrap()});assert_eq!(heap,(0,0));assert_eq!(birth.work_refusal().unwrap().message.as_ptr(),pointers[0]);assert_eq!(birth.receipt_refusal().unwrap().message.as_ptr(),pointers[1]);birth.phase=OriginalFailureStorageBirthPhase::Settled;let(turn,heap)=observe(||complete(birth.emit()));assert_eq!(heap,(0,0));assert_eq!(turn.work,0);let failure=turn.result.unwrap_err();assert_eq!(failure.work_refusal().unwrap().message.as_ptr(),pointers[0]);assert_eq!(failure.receipt_refusal().unwrap().message.as_ptr(),pointers[1]);assert!(birth.terminal_is_empty());}

struct GuardWork{source:std::sync::Arc<std::sync::atomic::AtomicUsize>,checks:std::sync::Arc<std::sync::atomic::AtomicUsize>}
impl crate::OriginalWorkRecipient for GuardWork{
 type Context<'turn,'source>=&'turn std::sync::atomic::AtomicUsize where 'source:'turn;
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn validate_context<'turn,'source>(&self,context:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{if std::ptr::eq(self.source.as_ref(),*context){Ok(())}else{Err(invalid("foreign performed failure Source"))}}
 fn admits<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,quote:crate::OriginalWorkQuote<'reply>,observed:u64,additional:u64)->crate::OriginalWorkQuoteComplete<'reply>where 'source:'turn{quote.complete(Ok(observed.checked_add(additional)==Some(1)))}
 fn settle_partial<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,check:crate::OriginalWorkPartialCheck<'reply>)->crate::OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{assert_eq!(context.load(std::sync::atomic::Ordering::SeqCst),1);self.checks.fetch_add(1,std::sync::atomic::Ordering::SeqCst);check.complete(self.validate_context(context))}
 fn recover_partial<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,check:crate::OriginalWorkPartialCheck<'reply>)->crate::OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.pending()}
}
#[test]
fn performed_failure_scope_claims_before_source_recovery_on_unwind(){
 use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};
 let all:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();let law=&all["performedGuard"];let source=Arc::new(AtomicUsize::new(0));let checks=Arc::new(AtomicUsize::new(0));let mut authority=crate::OriginalWorkAuthority::new(GuardWork{source:source.clone(),checks:checks.clone()});let mut context=source.as_ref();
 authority.with_loan(&mut context,|loan|{let mut loan=loan.reborrow();let mut work=crate::OriginalWork{state:crate::OriginalWorkState::fresh(),recipient:Some(&mut loan)};work.begin_turn();let mut birth=OriginalFailureStorageBirth::default();birth.phase=OriginalFailureStorageBirthPhase::WorkPrepare;assert_eq!(work.prepare_for_action(law["quoted"].as_u64().unwrap(),&mut birth.action).unwrap(),Some(true));birth.quoted=Some(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:std::mem::size_of::<AtomicUsize>(),maximum_depth:1,..Default::default()});birth.phase=OriginalFailureStorageBirthPhase::Allocate;
 let mut pool=OriginalFailureStoragePool::default();let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let mut scope=OriginalFailurePerformedScope::new(&mut work.state,&mut birth,&mut pool).unwrap();let mut effect=scope.effect();assert!(effect.performed(law["performed"].as_u64().unwrap()).unwrap());source.fetch_add(1,Ordering::SeqCst);panic!("actual original producer work precedes its physical marker")}));
 assert!(interrupted.is_err());assert_eq!(work.actual(),u128::from(law["scopeAtUnwind"].as_u64().unwrap()));assert_eq!(birth.work_claim.take().unwrap().unwrap(),work.actual());assert_eq!(birth.actual(),None);assert_eq!(checks.load(Ordering::SeqCst),0);let mut partial=None;assert!(work.settle_partial_for_action_into(birth.action,&mut partial).unwrap());let partial=partial.take().unwrap();assert_eq!(partial.total(),work.actual());assert!(partial.source_refusal().is_none());assert_eq!(checks.load(Ordering::SeqCst),law["sourceChecks"].as_u64().unwrap()as usize);birth.phase=OriginalFailureStorageBirthPhase::WorkCommit;assert!(work.commit_for_action(birth.work,birth.action,&mut birth.proof).unwrap());birth.phase=OriginalFailureStorageBirthPhase::Finishing;work.finish_for_action(&mut birth.proof,&mut birth.action).unwrap();birth.phase=OriginalFailureStorageBirthPhase::Settled;let turn=complete(birth.emit());assert_eq!(turn.work,u128::from(law["performed"].as_u64().unwrap()));assert_eq!(turn.result.unwrap().progress(),Default::default());assert!(birth.terminal_is_empty());
 }).unwrap();assert!(authority.into_recipient().is_ok());
}

#[test]
fn quoted_birth_prices_marker_and_intrusive_publication_headers(){let law:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();let row=law["layout"].as_array().unwrap().iter().find(|row|row["pointerBits"].as_u64()==Some(usize::BITS.into())).unwrap();assert_eq!(OriginalFailureStorage::admission_demand().copy_bytes,row["directCopyBytes"].as_u64().unwrap()as usize);assert_eq!(OriginalFailureStorage::birth_demand().copy_bytes,row["pooledCopyBytes"].as_u64().unwrap()as usize);}

#[test]
fn actual_allocator_waits_for_its_original_partial_source_without_replay(){
 let law:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();let law=&law["partial"];let mut funding=Funding::new();funding.partial_pending.store(true,Ordering::SeqCst);
 let(first,heap)=observe(||refill_original_failure_storage(&mut funding,grant()));assert!(matches!(first,crate::RetainedWorkPoll::Pending{..}));assert_eq!(heap,(OriginalFailureStorage::birth_bytes(),0));assert_eq!(first.work(),u128::from(law["firstWork"].as_u64().unwrap()));assert_eq!(funding.state.actual(),1);assert_eq!(funding.birth.phase(),OriginalFailureStorageBirthPhase::WorkPartial);assert!(!funding.pool.is_empty());assert!(funding.birth.work_proof().is_none());assert_eq!(funding.posts,0);assert_eq!(funding.checks.load(Ordering::SeqCst),law["checks"].as_u64().unwrap()as usize);
 let(second,heap)=observe(||complete(refill_original_failure_storage(&mut funding,grant())));assert_eq!(heap,(0,0));assert_eq!(second.work,u128::from(law["resumeWork"].as_u64().unwrap()));let progress=second.result.unwrap().progress();assert_eq!(progress.copied_bytes,OriginalFailureStorage::birth_demand().copy_bytes);assert_eq!(progress.retained_capacity_bytes,OriginalFailureStorage::birth_bytes());assert_eq!(funding.recoveries.load(Ordering::SeqCst),law["recoveryCalls"].as_u64().unwrap()as usize);assert_eq!((funding.prepared,funding.quotes,funding.posts),(1,1,1));funding.release();
}
#[test]
fn insufficient_header_grant_settles_before_opening_original_work(){let mut funding=Funding::new();let denied=RetainedCloneGrant{maximum_copy_bytes:grant().maximum_copy_bytes-1,..grant()};let(turn,heap)=observe(||complete(refill_original_failure_storage(&mut funding,denied)));assert_eq!(heap,(0,0));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(funding.prepared,0);assert!(funding.birth.terminal_is_empty());let turn=complete(refill_original_failure_storage(&mut funding,grant()));assert_eq!(turn.work,1);assert!(turn.result.is_ok());funding.release();}

#[test]
fn actual_partial_source_unwind_keeps_its_owned_refusal_and_the_allocated_node(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();let law=&fixture["partialUnwind"];let mut funding=Funding::new();let error=ValueError::new(ValueRefusalKind::Canceled,law["refusal"].as_str().unwrap().to_owned());let pointer=error.message.as_ptr();*funding.partial_refusal.lock().unwrap()=Some(error);funding.partial_panic.store(true,Ordering::SeqCst);
 let(interrupted,heap)=observe(||std::panic::catch_unwind(std::panic::AssertUnwindSafe(||refill_original_failure_storage(&mut funding,grant()))));assert!(interrupted.is_err());assert!(heap.0>=OriginalFailureStorage::birth_bytes());assert_eq!(funding.state.actual(),u128::from(law["scopeAtUnwind"].as_u64().unwrap()));assert_eq!(funding.birth.phase(),OriginalFailureStorageBirthPhase::WorkPartial);assert!(!funding.pool.is_empty());assert!(funding.birth.work_proof().is_none());assert_eq!(funding.posts,0);
 let(turn,heap)=observe(||complete(refill_original_failure_storage(&mut funding,grant())));assert_eq!(heap,(0,0));assert_eq!(turn.work,u128::from(law["reportedOnResume"].as_u64().unwrap()));let failure=turn.result.unwrap_err();assert_eq!(failure.work_refusal().unwrap().message.as_ptr(),pointer);assert_eq!(failure.retained_progress().retained_capacity_bytes,OriginalFailureStorage::birth_bytes());assert_eq!(funding.checks.load(Ordering::SeqCst),law["receiveCalls"].as_u64().unwrap()as usize);assert_eq!(funding.recoveries.load(Ordering::SeqCst),law["recoverCalls"].as_u64().unwrap()as usize);assert_eq!((funding.prepared,funding.quotes,funding.posts),(1,1,1));funding.release();
}

#[test]
fn settlement_refusals_retry_the_same_original_commit_and_finish_without_reallocation(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();let law=&fixture["settlementRetry"];let mut funding=Funding::new();let commit=ValueError::new(ValueRefusalKind::Canceled,"actual commit preflight refusal".to_owned());let finish=ValueError::new(ValueRefusalKind::Canceled,"actual finish preflight refusal".to_owned());let pointers=[commit.message.as_ptr(),finish.message.as_ptr()];funding.commit_refusal=Some(commit);funding.finish_refusal=Some(finish);
 let(first,heap)=observe(||refill_original_failure_storage(&mut funding,grant()));assert!(matches!(first,crate::RetainedWorkPoll::Pending{..}));assert_eq!(heap,(OriginalFailureStorage::birth_bytes(),0));assert_eq!(first.work(),u128::from(law["firstWork"].as_u64().unwrap()));assert_eq!(funding.birth.phase(),OriginalFailureStorageBirthPhase::WorkCommit);let action=funding.birth.work_action();assert!(action.is_some());assert!(funding.birth.work_proof().is_none());
 let(second,heap)=observe(||refill_original_failure_storage(&mut funding,grant()));assert!(matches!(second,crate::RetainedWorkPoll::Pending{..}));assert_eq!(heap,(0,0));assert_eq!(second.work(),u128::from(law["secondWork"].as_u64().unwrap()));assert_eq!(funding.birth.phase(),OriginalFailureStorageBirthPhase::Finishing);assert_eq!(funding.birth.work_action(),action);assert!(funding.birth.work_proof().is_some());
 let(third,heap)=observe(||complete(refill_original_failure_storage(&mut funding,grant())));assert_eq!(heap,(0,0));assert_eq!(third.work,u128::from(law["lastWork"].as_u64().unwrap()));let failure=third.result.unwrap_err();assert_eq!(failure.work_refusal().unwrap().message.as_ptr(),pointers[0]);assert_eq!(failure.receipt_refusal().unwrap().message.as_ptr(),pointers[1]);assert_eq!(failure.retained_progress().retained_capacity_bytes,OriginalFailureStorage::birth_bytes());assert_eq!(funding.commits,law["commits"].as_u64().unwrap()as usize);assert_eq!(funding.finishes,law["finishes"].as_u64().unwrap()as usize);assert_eq!((funding.prepared,funding.quotes,funding.posts),(1,1,1));funding.release();
}
